package mphf

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// A `.mphf` file is a small text preface, a blank line and the binary content:
//
//	MPHF\n
//	generated by: Ember Nexus API 0.2.0\n
//	generated on: 2026-11-22 18:14\n
//	content length: 1234567\n
//	sha256: <64 hex characters>[spaces]\n
//	\n
//	<content>
//
// The content starts after the first "\n\n" of the file. `head` or `cut` therefore show where a file comes from, and
// a reader can check the length and the hash without understanding the content. The spaces after the hash only pad
// the preface to a multiple of 64 bytes, so the sections of the content keep their alignment inside the file. Lines
// this reader does not know are ignored, `content length` and `sha256` are required.
//
// Alignment rules (checked by the writer and by every reader, see checkAlignment): the content starts at an offset
// which is a multiple of 64; the only padding are spaces directly behind the hash, fewer than 64 of them; no other
// line ends with a space.
const (
	preambleMagic   = "MPHF"
	preambleHashKey = "sha256"
	// maxPreambleSize bounds the search for the end of the preface.
	maxPreambleSize = 1024
	// DefaultGenerator is used if BuildOptions.Generator is empty.
	DefaultGenerator = "mphf-builder"
)

type preamble struct {
	generator     string
	generatedOn   string
	contentLength uint64
	sha256        [sha256.Size]byte
	// contentOffset is the offset of the first content byte inside the file.
	contentOffset int
}

func validateGenerator(s string) error {
	if len(s) > 200 {
		return fmt.Errorf("generator is longer than 200 bytes")
	}
	if strings.HasSuffix(s, " ") {
		return fmt.Errorf("generator ends with a space")
	}
	for _, c := range []byte(s) {
		if c < 0x20 || c == 0x7f {
			return fmt.Errorf("generator contains control characters")
		}
	}
	return nil
}

func encodePreamble(generator string, createdAtMs, contentLength uint64, sum [sha256.Size]byte) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(preambleMagic + "\n")
	b.WriteString("generated by: " + generator + "\n")
	b.WriteString("generated on: " + time.UnixMilli(int64(createdAtMs)).UTC().Format("2006-01-02 15:04") + "\n")
	b.WriteString("content length: " + strconv.FormatUint(contentLength, 10) + "\n")
	b.WriteString(preambleHashKey + ": " + hex.EncodeToString(sum[:]))
	if pad := (sectionAlign - (b.Len()+2)%sectionAlign) % sectionAlign; pad > 0 {
		b.WriteString(strings.Repeat(" ", pad))
	}
	b.WriteString("\n\n")
	// the writer holds itself to the rules every reader enforces
	if _, err := parsePreamble(b.Bytes()); err != nil {
		return nil, fmt.Errorf("internal error: the written preface violates its own rules: %w", err)
	}
	return b.Bytes(), nil
}

// parsePreamble reads the preface of a complete file.
func parsePreamble(file []byte) (*preamble, error) {
	head := file
	if len(head) > maxPreambleSize {
		head = head[:maxPreambleSize]
	}
	end := bytes.Index(head, []byte("\n\n"))
	if end < 0 {
		return nil, formatErr("no end of preface within the first %d bytes", maxPreambleSize)
	}
	p := &preamble{contentOffset: end + 2}
	lines := strings.Split(string(head[:end]), "\n")
	if lines[0] != preambleMagic {
		return nil, formatErr("bad magic")
	}
	if err := checkAlignment(p.contentOffset); err != nil {
		return nil, err
	}
	var haveLength, haveHash bool
	for _, line := range lines[1:] {
		key, rawValue, ok := strings.Cut(line, ": ")
		if !ok {
			return nil, formatErr("malformed preface line %q", line)
		}
		value := strings.TrimRight(rawValue, " ")
		if padding := len(rawValue) - len(value); padding > 0 && (key != preambleHashKey || padding >= sectionAlign) {
			return nil, formatErr("line %q has %d trailing spaces; only the %s line may have fewer than %d", key, padding, preambleHashKey, sectionAlign)
		}
		switch key {
		case "generated by":
			p.generator = value
		case "generated on":
			p.generatedOn = value
		case "content length":
			n, err := strconv.ParseUint(value, 10, 63)
			if err != nil {
				return nil, formatErr("bad content length %q", value)
			}
			p.contentLength, haveLength = n, true
		case preambleHashKey:
			raw, err := hex.DecodeString(value)
			if err != nil || len(raw) != sha256.Size || strings.ToLower(value) != value {
				return nil, formatErr("bad %s value", preambleHashKey)
			}
			copy(p.sha256[:], raw)
			haveHash = true
		}
	}
	if !haveLength || !haveHash {
		return nil, formatErr("preface lacks content length or %s", preambleHashKey)
	}
	return p, nil
}

// checkAlignment enforces that the content starts at a multiple of 64 bytes, so its sections keep their alignment
// inside the (page aligned) mapping.
func checkAlignment(contentOffset int) error {
	if contentOffset%sectionAlign != 0 {
		return formatErr("content starts at offset %d, which is not a multiple of %d", contentOffset, sectionAlign)
	}
	return nil
}
